class InvariantViolationError(Exception):
    """Raised when a financial invariant check fails."""
    pass


class HighRiskModule23:
    """
    Financial Invariants domain module for handling high-risk operations
    with mandatory invariant validation.
    """

    def validate_invariant(self, payload: dict) -> bool:
        """
        Validates the financial invariant for the given payload.

        Rules:
        - Payload must be a dictionary.
        - If 'amount' is present, must be numeric and non-negative.
        - If 'account_status' is present, must be 'ACTIVE'.
        - If 'valid' is present and False, raises an error.

        Raises:
            InvariantViolationError: If any invariant condition is violated.
        """
        if not isinstance(payload, dict):
            raise InvariantViolationError("Payload must be a dictionary.")

        if "valid" in payload and not payload["valid"]:
            raise InvariantViolationError("Financial invariant violated: 'valid' cannot be False.")

        if "amount" in payload:
            amount = payload["amount"]
            if not isinstance(amount, (int, float)):
                raise InvariantViolationError("Field 'amount' must be a numeric value.")
            if amount < 0:
                raise InvariantViolationError("Financial invariant violated: 'amount' cannot be negative.")

        if "account_status" in payload:
            if payload["account_status"] != "ACTIVE":
                raise InvariantViolationError("Financial invariant violated: 'account_status' must be 'ACTIVE'.")

        return True

    def execute(self, payload: dict) -> dict:
        """
        Executes the high-risk module operation after validating invariants.
        """
